613	test("a repository whose own Git configuration names a program is not hashed: the binding is unavailable and nothing runs", { skip: process.platform !== "linux" }, () => {
614	  // Each case is a way a checkout can make Git run a command while it hashes a changed file. The marker file is the proof.
615	  const cases: Array<[string, (workspace: string, command: string) => void]> = [
616	    ["a clean filter", (workspace, command) => {
617	      fs.writeFileSync(path.join(workspace, ".gitattributes"), "* filter=planted\n");
618	      git(workspace, "config", "filter.planted.clean", command);
619	    }],
620	    ["a filter named only in .git/info/attributes", (workspace, command) => {
621	      fs.mkdirSync(path.join(workspace, ".git", "info"), { recursive: true });
622	      fs.writeFileSync(path.join(workspace, ".git", "info", "attributes"), "* filter=planted\n");
623	      git(workspace, "config", "filter.planted.clean", command);
624	    }],
625	    ["a filter defined in an included file", (workspace, command) => {
626	      fs.writeFileSync(path.join(workspace, ".gitattributes"), "* filter=planted\n");
627	      const included = path.join(workspace, ".git", "planted.inc");
628	      // Quoted: an unquoted `;` starts a comment in a Git configuration file and would cut the command short.
629	      fs.writeFileSync(included, `[filter "planted"]\n\tclean = "${command}"\n`);
630	      git(workspace, "config", "include.path", included);
631	    }],
632	    ["a file-system monitor", (workspace, command) => git(workspace, "config", "core.fsmonitor", command)],
633	    ["an attributes file named by the repository", (workspace, command) => {
634	      const attributes = path.join(workspace, ".git", "planted.attributes");
635	      fs.writeFileSync(attributes, "* filter=planted\n");
636	      git(workspace, "config", "core.attributesFile", attributes);
637	      git(workspace, "config", "filter.planted.clean", command);
638	    }],
639	  ];
640	  for (const [name, plant] of cases) {
641	    const subject = savedSubject({ flight: false });
642	    if (!fs.existsSync(path.join(subject.workspace, ".git"))) git(subject.workspace, "init", "-q");
643	    fs.writeFileSync(path.join(subject.workspace, "tracked.txt"), "tracked\n");
644	    git(subject.workspace, "add", "-A");
645	    git(subject.workspace, "-c", "user.name=t", "-c", "user.email=t@example.invalid", "commit", "-q", "-m", "base");
646	    setReceiptCandidateId(subject, "0".repeat(64));
647	    // The tracked file keeps its content and size and gets a new modification time: Git cannot tell whether it changed
648	    // without hashing it again, and hashing is what runs a content filter. (A file whose size changed is known to be
649	    // modified without being read.) Done before the plant: the test's own Git commands would otherwise run the
650	    // planted program themselves.
651	    const later = new Date(Date.now() + 5_000);
652	    fs.utimesSync(path.join(subject.workspace, "tracked.txt"), later, later);
653	    const marker = path.join(subject.root, "ran");
654	    plant(subject.workspace, `sh -c 'echo ran > ${marker}; cat'`);
655	    assert.equal(fs.existsSync(marker), false, `${name}: planting ran the command`);
656	
657	    const exported = exportChecked(subject.request({ out: path.join(subject.root, "out", "hostile") }));
658	    const binding = JSON.parse(bundleTexts(exported.written.dir)["receipts/candidate-binding.json"]);
659	    assert.equal(fs.existsSync(marker), false, `${name}: the configured command ran`);
660	    assert.equal(binding.status, "unavailable", name);
661	    assert.equal(binding.unavailable_reason, "workspace_configures_git_programs", name);
662	    assert.equal(binding.current_candidate_id, null, name);
663	  }
664	});
