      fs.mkdirSync(subSrc, { recursive: true });
      git(subSrc, "init", "-q");
      fs.writeFileSync(path.join(subSrc, "s.txt"), "s\n");
      git(subSrc, "add", "-A");
      git(subSrc, ...IDENT, "commit", "-q", "-m", "sub");
      git(ws, ...IDENT, "-c", "protocol.file.allow=always", "submodule", "add", subSrc, "sub");
      git(ws, ...IDENT, "commit", "-q", "-m", "add sub");
      bumpTarget = path.join(ws, "sub", "s.txt");
    } else {
      baseInit(ws, root);
    }

    setReceiptCandidateId(subject, "0".repeat(64));

    const later = new Date(Date.now() + 5_000);
    fs.utimesSync(bumpTarget, later, later);

    if (opts.special14) {
      // plant filter inside submodule's real gitdir + its .gitattributes
      fs.appendFileSync(path.join(ws, ".git", "modules", "sub", "config"), `[filter "p"]\n\tclean = "${c.filterCmd}"\n`);
      fs.writeFileSync(path.join(ws, "sub", ".gitattributes"), "* filter=p\n");
    } else {
      plant(c);
    }

    if (fs.existsSync(marker)) { console.log(`PLANT-RAN ${name}`); return; }

    let executed = false;
    let status = "-";
    let reason = "-";
    try {
      const exported = exportChecked(subject.request({ out: path.join(root, "out", "hostile") }));
      const binding = JSON.parse(bundleTexts(exported.written.dir)["receipts/candidate-binding.json"]);
      status = binding.status;
      reason = binding.unavailable_reason ?? "-";
    } catch (err) {
      status = `EXPORT_ERR(${err instanceof Error ? err.message : String(err)})`;
    }
    executed = fs.existsSync(marker);
    console.log(`RESULT ${name}: ${executed ? "EXECUTED" : "not executed"} binding=${status} reason=${reason}`);
  } catch (err) {
    console.log(`RESULT ${name}: ERROR ${err instanceof Error ? err.message : String(err)}`);
  }
}

test("probe: git-program-config bypass sweep", { skip: process.platform !== "linux" }, () => {
  for (const c of cases) runCase(c.name, c.plant);
  runCase("14-submodule", () => {}, { special14: true });
});
